using namespace stalthos;using namespace stalthos::fauna;
void need(bool b,const char*m){if(!b)throw std::runtime_error(m);}
double consumed(const ResourceLedgerDto&d,Identity id){for(const auto&r:d.resources)if(r.id==id)return r.consumedQuantity;throw std::runtime_error("resource missing");}
engine::NativePopulationRegistry fixture(bool correct){std::vector<HabitatSite>s{{{0,0,0},true,false,{1}},{{2,0,0},false,true,{0,2}},{{4,0,0},false,false,{1}}};Population p(42,1001,s,2,{1});auto old=p.snapshot();need(!p.connectedDiet(),"original diet changed");p.setSiteResources(0,false,false);need(p.snapshot().habitatSignature==old.habitatSignature,"availability changed original signature");p.setSiteResources(0,true,false);need(p.appendCarrionBranch({{4.5,0,0}},2),"supported leaf append failed");need(!p.appendCarrionBranch({{5,0,0}},2),"duplicate branch admitted");need(p.connectedDiet()&&p.carrionSite()==3,"immutable tag missing");auto snap=p.snapshot();for(unsigned i=0;i<2;++i){auto&a=snap.actors[i];a.id=i?88:77;a.species=i?HeroSpecies::Smalltrotter:HeroSpecies::Longstride;a.calendarAge=i?4000:7000;a.stage=LifeStage::Adult;a.site=(i==0)==correct?3:0;a.target=a.site;a.position=p.sites()[a.site].position;a.activity=Activity::Browse;a.hunger=.8;a.thirst=.1;a.fatigue=.1;a.isResting=false;}p.restore(snap,{1});ResourceLedgerDto ledger{{{100,ResourceKind::Creek,10,1},{200,ResourceKind::Shrub,10,0},{211,ResourceKind::Shrub,1,0}},{{90,100,1}}};std::uint64_t next=110;return engine::NativePopulationRegistry(p,ledger,{{77,100},{88,101}},{{0,200,{0,0,0}},{1,100,{2,0,0}},{3,211,{4.5,0,0}}},next);}
int main(){try{auto wrong=fixture(false);auto core=wrong.registry();auto before=core.continuationSnapshot();need(!core.contact(1001,77,100,0,200,.2,RegionalAdmissionOrigin::PhysicalArrival).event,"Longstride ate plant");need(!core.contact(1001,88,101,3,211,.2,RegionalAdmissionOrigin::PhysicalArrival).event,"herbivore ate carrion");need(consumed(core.snapshot(1001)->ledger,200)==0&&consumed(core.snapshot(1001)->ledger,211)==0,"wrong diet mutated ledger");need(core.snapshot(1001)->population.actors[0].hunger==.8&&core.snapshot(1001)->population.actors[1].hunger==.8,"wrong diet relief");wrong.advance({1,2},true);need(wrong.snapshot().actors[0].hunger>=.8&&wrong.snapshot().actors[1].hunger>=.8,"local wrong-diet relief");
 auto host=fixture(true);const auto bindings=host.sessions();const auto sig=host.snapshot().habitatSignature;need(host.consume(999,211,.6),"hero shared transfer failed");need(!host.consume(999,211,.6),"hero replay accepted");host.advance({1,2},true);need(consumed(host.ledger(),211)>.6&&host.snapshot().actors[0].hunger<.8,"actual NPC carrion contact/relief absent");need(host.snapshot().actors[0].calendarAge==7002&&host.sessions()==bindings,"clock or binding reset");core=host.registry();double prior=0;for(const auto& key:host.ledger().sessions)if(key.sessionId==100&&key.resourceId==211)prior=key.amount;auto replay=core.contact(1001,77,100,3,211,prior,RegionalAdmissionOrigin::PhysicalArrival);need(!replay.event,"NPC cumulative replay duplicated");need(!core.contact(1001,77,100,3,211,prior+.01,RegionalAdmissionOrigin::CameraPrewarm).event,"camera-origin contact accepted");need(!core.contact(1001,77,101,3,211,prior+.01,RegionalAdmissionOrigin::PhysicalArrival).event,"alien session accepted");
 const auto dormantBefore=host.ledger();host.advanceDormant({3,5});need(consumed(host.ledger(),211)==consumed(dormantBefore,211),"dormant consumption");need(host.snapshot().actors[0].calendarAge==7007,"dormant clock not once");host.advance({40,1},true);need(consumed(host.ledger(),211)==1,"finite competition not exactly exhausted");need(host.snapshot().habitatSignature==sig,"depletion changed immutable signature");need(host.sessions()==bindings&&host.ledger().sessions.front().sessionId==90&&host.ledger().sessions.front().amount==1,"old binding/history lost");core=host.registry();need(core.restoreContinuation(host.continuation()),"depleted continuation rejected");need(!core.contact(1001,77,100,3,211,1,RegionalAdmissionOrigin::PhysicalArrival).event,"exhausted contact produced event");need(engine::connected_save::configuration(false)!=202610230100ULL,"STLC old diet config not invalidated");
 SimCore clock;StalthosState world(42);world.setHero(1,1);auto h=persistence::captureSave(clock,world,persistence::HostPose{{0,0,0},0,0},persistence::CameraStateSnapshot{});h.heroLifecycle=persistence::HeroLifecycleSnapshot{1,HeroSpecies::Longstride,0,LifeStage::Hatchling};h.heroNeeds=persistence::HeroNeedsSnapshot{1,HeroSpecies::Longstride,.2,.3,.1,0,false};h.faunaPopulation=host.snapshot();h.faunaResourceSessions=host.sessions();h.resourceLedger=host.ledger();engine::connected_save::Candidate saved{{h,host.continuation(),engine::connected_save::configuration(false),1},1001,999,1,.2};auto encoded=engine::connected_save::encode(saved);auto decoded=engine::connected_save::decode(encoded,saved.simulation.configuration);auto restored=engine::connected_save::restore(decoded,host,saved.simulation.configuration);need(restored.fauna->snapshot().habitatSignature==sig&&consumed(restored.fauna->ledger(),211)==1&&restored.fauna->sessions()==bindings,"depleted diet STLC restoration changed ownership");saved.simulation.configuration=202610230100ULL;auto old=engine::connected_save::encode(saved);bool rejected=false;try{engine::connected_save::decode(old,engine::connected_save::configuration(false));}catch(const std::exception&){rejected=true;}need(rejected,"oldSTLC diet checkpoint accepted by newprofile");const std::filesystem::path ownedOld="var/review-npc-carrion/old.stlc";{std::ofstream out(ownedOld,std::ios::binary);out.write(old.data(),old.size());}saved.simulation.configuration=engine::connected_save::configuration(false);rejected=false;try{engine::connected_save::write(ownedOld,saved,host,saved.simulation.configuration);}catch(const std::exception&){rejected=true;}need(rejected,"new diet overwrote old profile");{std::ifstream in(ownedOld,std::ios::binary);const std::string preserved{std::istreambuf_iterator<char>(in),{}};need(preserved==old,"old checkpoint changed on refusal");}std::filesystem::remove(ownedOld);
 {std::vector<HabitatSite> s{{{0,0,0},true,true,{}}};Population malformed(42,1001,s,0);need(malformed.appendCarrionBranch({{.5,0,0}},0),"malformed fixture branch");malformed.setSiteResources(1,false,true);ResourceLedgerDto bad{{{211,ResourceKind::Creek,1,0}}, {}};RegionalPopulationRegistry rejected(malformed,bad,{4,4},{});need(!rejected.configureContacts(1001,{{1,211,{.5,0,0}}}),"211 masquerading as creek admitted");}
 std::cout<<"NPC_DIET_REVIEW_OK wrong-diet direct/local denial; actual shared hero/NPC finite competition; replay/foreign session/camera/dormant denial; one clock; retained history/bindings; depleted signature/continuation; oldSTLCconfig invalidated\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
